mapper.select:
select mor.refund_id as refundId, mor.refund_no as refundNo, mor.order_id as orderId, mo.order_no as orderNo, mor.account_id as accountId, a.nick_name as accountNickName, a.mobile as accountMobile, mor.refund_type as refundType, mor.refund_amount as refundAmount, mor.refund_status as refundStatus, mor.refund_reason as refundReason, mor.transaction_no as transactionNo, mor.apply_time as applyTime, mor.refund_time as refundTime, mor.handle_time as handleTime, mor.handle_remark as handleRemark, mor.del_flag as delFlag, mor.create_time as createTime, mor.update_time as updateTime, mor.remark as remark from mall_order_refund mor left join mall_order mo on mor.order_id = mo.order_id and mo.del_flag = 0 left join account a on mor.account_id = a.account_id and a.del_flag = 0 where mor.del_flag = 0
and mor.refund_no like concat('%', #{refundNo}, '%')
and mor.order_id = #{orderId}
and mo.order_no like concat('%', #{orderNo}, '%')
and mor.account_id = #{accountId}
and a.nick_name like concat('%', #{accountNickName}, '%')
and a.mobile like concat('%', #{accountMobile}, '%')
and mor.refund_type = #{refundType}
and mor.refund_status = #{refundStatus}
and mor.refund_reason like concat('%', #{refundReason}, '%')
order by mor.refund_id desc

select mor.refund_id as refundId, mor.refund_no as refundNo, mor.order_id as orderId, mor.account_id as accountId, mor.refund_type as refundType, mor.refund_amount as refundAmount, mor.refund_status as refundStatus, mor.refund_reason as refundReason, mor.transaction_no as transactionNo, mor.apply_time as applyTime, mor.refund_time as refundTime, mor.handle_time as handleTime, mor.handle_remark as handleRemark, mor.del_flag as delFlag, mor.create_time as createTime, mor.update_time as updateTime, mor.remark as remark from mall_order_refund mor where mor.del_flag = 0
and mor.refund_no = #{refundNo}
and mor.order_id = #{orderId}
and mor.account_id = #{accountId}
and mor.refund_type = #{refundType}
and mor.refund_status = #{refundStatus}
order by mor.refund_id desc

select count(1)
from mall_order_refund mor
where mor.del_flag = 0

    and mor.refund_no = #{refundNo}


    and mor.order_id = #{orderId}


    and mor.account_id = #{accountId}


    and mor.refund_type = #{refundType}


    and mor.refund_status = #{refundStatus}

select mor.refund_id, mor.refund_no, mor.order_id, mor.account_id, mor.refund_type, mor.refund_amount, mor.refund_status, mor.refund_reason, mor.transaction_no, mor.apply_time, mor.refund_time, mor.handle_time, mor.handle_remark, mor.del_flag, mor.create_time, mor.update_time, mor.remark from mall_order_refund mor where mor.del_flag = 0
and mor.refund_no = #{refundNo}
and mor.order_id = #{orderId}
and mor.account_id = #{accountId}
and mor.refund_type = #{refundType}
and mor.refund_status = #{refundStatus}
order by mor.refund_id desc limit 1

